        { name: 'nodejs', _count: { articles: 5 } },
      ];
      prisma.tag.groupBy.mockResolvedValue(mockPopularTags);

      // Act
      const result = await tagService.getPopularTags(3);

      // Assert
      expect(prisma.tag.groupBy).toHaveBeenCalledWith({
        by: ['name'],
        _count: { articles: true },
        orderBy: { _count: { articles: 'desc' } },
        take: 3,
      });
      expect(result).toEqual(mockPopularTags);
    });

    it('should handle limit parameter correctly', async () => {
